window.STORY_CHAPTERS["c66f4a278e22ec098"]={"id":"c66f4a278e22ec098","lines":[{"uid":"talk.vc.home_event_asuna_sao_sleeping_6#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"好呀，反正不管你撒什么谎，只要看着你的眼睛，我就能知道是真是假了。","en":"Lie to your heart's content! If I look in your eyes, I'll know the whole truth anyway.","ja":"いいよ、どんな嘘をついても君の目を見れば、全部わかっちゃうんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_7#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不知道这个世界有没有连假……有的话，真想和你一起去旅行。","en":"Are there week-long holidays in this world? If so...then I'd love to go traveling with you.","ja":"この世界にも連休ってあるのかな……もしあるならふたりだけで旅行に行きたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_8#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天下雨……要不要在家好好休息呢？偶尔这样也不错吧？","en":"It's raining today...so why don't we relax at home? We deserve a break, don't we?","ja":"今日は雨だから……おうちでゆっくりしようかたまにはいいよね?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_9#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"要是你陷入危机，就算你在银河的另一端，我也会赶去救你。","en":"If you're ever in trouble, I'll fly to your rescue, even if I have to cross the Milky Way.","ja":"もし君がピンチだったら天の川の向こうからだって助けに行くからね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_10#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_10","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"最近有很多庆典，所以我试着做了类似章鱼烧的料理。","en":"Since it's street festival season in Japan right now, I made us lots of grilled food.","ja":"今はお祭りのシーズンだからたこ焼きっぽい料理を作ってみたの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_11#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"在休假期间内，我们经历了许多美好的事情呢。这些回忆全都是我的宝物。","en":"We made so many memories during this vacation. Each and every one of them is a treasure to me.","ja":"お休みの間、たくさん思い出作れたね全部、わたしの宝物"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_12#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_12","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"好漂亮的满月，怎么看都不像是VR……回到现实后，再一起赏月吧。","en":"What a beautiful moon! Hard to believe we're in VR... I hope I can see the real thing again someday.","ja":"VRとはとても思えない綺麗な満月だね……現実に帰っても、一緒に見たいな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_13#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_13","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是万圣节，所以我做了南瓜汤。肯定很好喝，你喝看看吧。","en":"Since it's Halloween, I made pumpkin soup. Want to have a taste? It's my own recipe.","ja":"今日はハロウィンにちなんでカボチャのスープを作ったの自信作だから、食べてみて"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_14#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_14","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"到了这个日子我就会回想起来。一开始的绝望，接着是你拯救我的英姿。","en":"Whenever this day comes, I always remember my initial despair...and how you rescued me from it.","ja":"この日になると思い出すの最初の頃の絶望と、そこから救ってくれた君の姿を"},"kind":"dialogue"},{"uid":"talk.vc.home_event_asuna_sao_sleeping_15#originalText","id":"talk.vc.home_event_asuna_sao_sleeping_15","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"在西方，圣诞节好像都是全家人一起过的。那我们也算是家人了……对吧？","en":"I hear that in the West, Christmas is a family holiday. Well, I guess we're also family...right?","ja":"本場では、クリスマスは家族と過ごすんだってなら、わたしたちも家族……かな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_sao_sleeping_3#originalText","id":"talk.vc.home_bd_asuna_sao_sleeping_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天是特别的日子，要早点回来喔。我会准备好吃的等你回来。","en":"Today is a special day, so please come back early. I'll cook you a big feast.","ja":"今日は特別な日だから早く帰ってきてねご馳走作って待ってるから"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_sao_sleeping_14#originalText","id":"talk.vc.home_bd_asuna_sao_sleeping_14","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"莉兹的生日，是不是送个对生意有帮助的东西比较好？这样她应该会比较开心。","en":"Should we give Liz a blacksmithing tool for her birthday? I'm sure she'd love that.","ja":"リズの誕生日はお店で使える物を贈ろうかそれが一番喜ばれるよね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_asuna_sao_sleeping_15#originalText","id":"talk.vc.home_bd_asuna_sao_sleeping_15","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"因为是西莉卡的生日，我和艾基尔先生商量后，煮了很多美味的料理。","en":"Since it's Silica's birthday, Agil and I worked together to cook her a big feast.","ja":"シリカちゃんの誕生日だからエギルさんと相談して、立派なご馳走を作ったんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_asuna_sao_sleeping_1#originalText","id":"talk.vc.home_rank_asuna_sao_sleeping_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"已经升级了吗？我也得追上你才行。不然就要被抛在后面了。","en":"Did you rank up already? I've got some catching up to do! I don't want to be left behind.","ja":"もうランクアップしたの?わたしも追いつかないと!置いて行かれちゃうもんね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_asuna_sao_sleeping_2#originalText","id":"talk.vc.home_rank_asuna_sao_sleeping_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"总觉得你好像变壮了。既然是VR，照理说外观应该不会变才对……","en":"I think you've bulked up a little. Strange...this is a VR, so your appearance shouldn't change...","ja":"なんだかたくましくなったねVRだから、外見は変わらないはずなのに……"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_asuna_sao_sleeping_3#originalText","id":"talk.vc.home_rank_asuna_sao_sleeping_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不能总是被你保护，我也必须继续变强，这样才能保护你。","en":"You're always coming to my rescue. I need to get stronger so that I can rescue you back.","ja":"君に守られてばっかりじゃなくわたしも君を守れるように強くならないと"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_asuna_sao_sleeping_4#originalText","id":"talk.vc.home_rank_asuna_sao_sleeping_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你有多厉害，在你身旁的我是最清楚的。因为你一直都很努力嘛。","en":"I know just how strong you are— I've seen how hard you had to work for it.","ja":"君の強さは、そばにいるわたしが一番よくわかってるよずっと努力してたもんね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_asuna_sao_sleeping_5#originalText","id":"talk.vc.home_rank_asuna_sao_sleeping_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你绝对能通关《艾恩葛朗特》。到时候，我也会在你身边。","en":"If anyone can clear Aincrad, it's you. And I'll be with you every step of the way.","ja":"君なら絶対、この《アインクラッド》をクリアできるその時は、わたしもそばにいるから"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_asuna_sao_sleeping_1#originalText","id":"talk.vc.home_etc_asuna_sao_sleeping_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"任务完成了啊。恭喜！报酬是什么呢？","en":"Congratulations on clearing the quest! So, what was your reward?","ja":"クエストクリアしたんだおめでとう!報酬はなんだったの?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_asuna_sao_sleeping_2#originalText","id":"talk.vc.home_etc_asuna_sao_sleeping_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"难得有人送礼物来，不打开来看看吗？","en":"You got a present! Aren't you going to open it?","ja":"せっかくプレゼントが来てるのに、開けないの?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_asuna_sao_sleeping_3#originalText","id":"talk.vc.home_etc_asuna_sao_sleeping_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"又要开始继续攻略了呢。在那之前，只要再一下下就好……可以靠在你身上吗？","en":"Oh dear, it's time for the next raid. Before we have to go... can we snuggle a bit longer?","ja":"次の攻略が始まっちゃうねその前に、もう少しだけ……くっついてもいい?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_2nd_anniv_1#originalText","id":"talk.vc.home_wait_alice_uw_2nd_anniv_1","speaker":{"cn":"莉法","en":"Leafa","ja":"アリス"},"text":{"cn":"我终于也有后辈了。我相信集成骑士的传承一定会源远流长的。","en":"At last, I have a pupil of my own. I am honored to help pass on our traditions to future generations.","ja":"ついに私にも後輩の騎士ができました。きっと整合騎士の系譜は遠い未来まで続いていくのですね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_2nd_anniv_2#originalText","id":"talk.vc.home_wait_alice_uw_2nd_anniv_2","speaker":{"cn":"莉法","en":"Leafa","ja":"アリス"},"text":{"cn":"看着飞龙牠们，不禁会希望牠们能不参与危险的战斗，一直天真无邪地玩耍下去。","en":"When I watch the dragons at play, I wish they could remain innocent and be spared from dangerous wars.","ja":"飛竜たちを見ていると、危険な戦などには行かせずに、ずっと無邪気に遊んでいて欲しいと思ってしまいます"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_2nd_anniv_3#originalText","id":"talk.vc.home_wait_alice_uw_2nd_anniv_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我总是很依赖骑士长阁下。虽然我也明白自己这样有失骑士风范……","en":"I'm always more childish when I'm near the Commander. I know it's not very valiant of me, though.","ja":"騎士長閣下には、いつも甘えてしまいます。騎士らしくないとはわかっているのですが……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_2nd_anniv_4#originalText","id":"talk.vc.home_wait_alice_uw_2nd_anniv_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"集成骑士都是能以一挡千的强者。但是，人界幅员广大，我们的人手不足以顾及每个角落也是事实。","en":"Integrity Knights are very powerful, but we cannot deny that we are shorthanded to protect this world.","ja":"整合騎士は、皆一騎当千の強者しかし、この広い人界すべてを見回るには、人手が足りないのも事実です"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_2nd_anniv_5#originalText","id":"talk.vc.home_wait_alice_uw_2nd_anniv_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你的剑，原本也是树木呢。呵呵……发现一个你跟我的共同之处了。","en":"Your sword was once a tree, I see. Well, well... Looks like you and I have something in common.","ja":"お前の剣も、元は樹木なのですねふふ……お前と私の共通点をひとつ見つけてしまいました"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_2nd_anniv_6#originalText","id":"talk.vc.home_wait_alice_uw_2nd_anniv_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"希望有一天，可以亲眼见证你和骑士长阁下认真比试的样子。","en":"Someday, I would love to see an honest duel between you and the Commander.","ja":"いつか、お前と騎士長閣下の本気の立ち合いを、この目で見てみたいものです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_2nd_anniv_7#originalText","id":"talk.vc.home_wait_alice_uw_2nd_anniv_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"最高司祭大人确实神秘莫测……但我们没有资格去打探她的底细。","en":"The High Pontifex is indeed a woman of many mysteries, but we mustn't try to uncover those secrets.","ja":"最高司祭様は、確かに謎多き御方……ですが、それを詮索するなど許されることではありません"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_2nd_anniv_8#originalText","id":"talk.vc.home_wait_alice_uw_2nd_anniv_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你为什么能为了别人如此拼命？你明知道那样会让自己身心俱疲……","en":"How can you be so devoted to helping others? Surely you know of the risk to your own life...","ja":"お前はなぜ、人のためにそれほど必死になれるのですか。自分の心身を損なうこともわかっているのに……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_2nd_anniv_9#originalText","id":"talk.vc.home_wait_alice_uw_2nd_anniv_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……你是饿了，还是想睡？不管怎样，都不该在骑士面前露出那种呆愣的表情。","en":"Are you hungry? Or perhaps tired? In either case, you mustn't be so sluggish in a Knight's presence.","ja":"……空腹か、それとも眠気ですか?いずれにせよ、そのように呆けた顔を騎士の前でするものではありません"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_2nd_anniv_1#originalText","id":"talk.vc.home_touch_alice_uw_2nd_anniv_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"若要防御周全，或许应该戴上头盔才是……但那样会限缩视野，让我不能大展拳脚。","en":"I should probably wear a helmet for proper defense, but I hate fighting with such a narrow field of vision.","ja":"防御のためには、兜を被るべきなのかもしれませんが……視界が狭くなると戦いづらいのです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_2nd_anniv_2#originalText","id":"talk.vc.home_touch_alice_uw_2nd_anniv_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"头发的触感很好……？那、那是因为……我才刚洗完澡而已……","en":"You like the feel...of my hair? W-Well, I suppose you would! I just washed it...","ja":"髪の手触りがいい……ですか?そ、それは……先ほど入浴をしたばかりだから……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_2nd_anniv_3#originalText","id":"talk.vc.home_touch_alice_uw_2nd_anniv_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"突、突然摸我的脸……你要我有什么反应啦？在、在这种地方……","en":"H-How dare you touch my cheek! How am I supposed to respond? This's n-neither the time nor place...","ja":"い、いきなり頬を触って……どうしようというのですか?こ、こんな場所で……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_2nd_anniv_4#originalText","id":"talk.vc.home_touch_alice_uw_2nd_anniv_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你的手，是为了什么而存在的？难道不是为了挥舞刀剑吗？","en":"Why do you even have hands? To swing a sword, I assume?","ja":"お前のその手は、なんのためにあるのですか。剣を振るうためではないのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_2nd_anniv_5#originalText","id":"talk.vc.home_touch_alice_uw_2nd_anniv_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……我平时就有在锻炼，所以我想自己的身体一定比普通女性还来得结实……","en":"Well, I do train hard every day... so I'm sure my body is more muscular than other girls...","ja":"……日頃より鍛錬していますからきっと私の体は、市井の女性たちより固いと思います……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_2nd_anniv_6#originalText","id":"talk.vc.home_touch_alice_uw_2nd_anniv_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"对我的剑感到好奇吗？很遗憾，除了我以外的人都没办法使用这把剑。","en":"You wish to touch my sword? Sorry, but I do not allow anyone other than myself to handle it.","ja":"私の剣が気になるのですか?残念ですが、これは私以外の誰にも扱うことは出来ません"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_2nd_anniv_7#originalText","id":"talk.vc.home_touch_alice_uw_2nd_anniv_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"身为骑士，就该时时做好万全准备。为此，我才会一直将铠甲穿在身上。","en":"A Knight must always be prepared. That is why I always wear armor.","ja":"騎士たるもの、常に備えなければなりません。そのために、私はこうして鎧をまとっているのです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_2nd_anniv_8#originalText","id":"talk.vc.home_touch_alice_uw_2nd_anniv_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"住、住手！竟敢对骑士的身体做出这种……很、很痒啦！","en":"Hey! S-Stop that at once! How dare you tickle a Knight's body...","ja":"や、やめなさい!騎士の体を、そのような……く、くすぐったいです!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_2nd_anniv_1#originalText","id":"talk.vc.home_time_alice_uw_2nd_anniv_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你真的睡得很香呢。看着你的睡脸，让我不禁也有了睡意。","en":"You really do look cozy when you sleep... It's rather infectious.","ja":"本当に気持ちよさそうに寝ていますねお前の寝ている顔を見ているとこっちまで眠くなってきます"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_2nd_anniv_2#originalText","id":"talk.vc.home_time_alice_uw_2nd_anniv_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天是要出发运行任务的日子。……你愿意为我送行吗？","en":"I am leaving for an assignment today. ...Aren't you going to send me off?","ja":"今日は任務に出立する日です……見送っては、くれないのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_2nd_anniv_3#originalText","id":"talk.vc.home_time_alice_uw_2nd_anniv_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"早上要是睡懒觉的话，一整天都会慵懒提不起劲的。好了，快点振作起来！","en":"A sluggish start in the morning leads to a sluggish day overall. Come on! Sharpen up!","ja":"朝に怠けてしまうと、その一日ずっとダラダラしてしまいますよさあ、シャキッとなさい!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_2nd_anniv_4#originalText","id":"talk.vc.home_time_alice_uw_2nd_anniv_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天万里无云，连远方的山脉都看得很清楚呢。要不要驾着飞龙，稍微飞到远一点的地方看看呢？","en":"It's so clear today that even the distant mountains are visible. Shall we fly the dragons out there?","ja":"今日は良く晴れて、遠くの山々まではっきり見えますね。少し、飛竜で遠くまで飛んでみましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_2nd_anniv_5#originalText","id":"talk.vc.home_time_alice_uw_2nd_anniv_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你每次带来的点心都好吃得不得了呢。请问是从哪里找来的呢？","en":"The snacks you bring me are always so tasty. Where do you find them?","ja":"お前が持ってくる菓子はいつも大変おいしいですねどうやって見つけてくるのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_2nd_anniv_6#originalText","id":"talk.vc.home_time_alice_uw_2nd_anniv_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"话说回来，我不曾跟你认真比试到最后一刻呢。希望有一天能和你一较高下。","en":"Come to think of it, we've never seen a duel through to the end. I'd like to settle the score someday.","ja":"そういえば、お前とは最後まで立ち合ったことはありませんでしたねいつか決着をつけたいものです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_2nd_anniv_7#originalText","id":"talk.vc.home_time_alice_uw_2nd_anniv_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"以前只要入夜，我就会感到不安与寂寞，但自从遇见了你，这样的感受也越来越少了。","en":"I used to feel lonely and anxious at night...but ever since I met you, nights have been easier.","ja":"以前は、夜になると不安や寂しさを感じていましたが、お前と出会ってからは、それも少し薄れてきました"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_2nd_anniv_8#originalText","id":"talk.vc.home_time_alice_uw_2nd_anniv_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天一整天都不见你的人影，你是做什么去了？方便的话请说给我听听吧。","en":"I haven't seen you all day— what were you up to? If you want to talk, I'll listen.","ja":"今日一日、姿が見えませんでしたが何をしていたのですか?よかったら聞かせてください"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_2nd_anniv_9#originalText","id":"talk.vc.home_time_alice_uw_2nd_anniv_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天的星星很美呢。再加上如此皎洁明亮的露那利亚，这或许是我第一次看到如此美丽动人的夜空。","en":"The stars are so lovely tonight. And Lunaria is so bright... I've never seen a night so beautiful.","ja":"今日は星が綺麗ですねルナリアも明るくて、このような美しい夜は、初めてかもしれません"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_2nd_anniv_10#originalText","id":"talk.vc.home_time_alice_uw_2nd_anniv_10","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"每次跟你一起行动，就会害我不小心熬夜……明天早上你要记得叫醒我哦。","en":"I always find myself staying up too late when I'm with you... Please be sure to get up on time tomorrow.","ja":"お前に付き合っていると、つい夜更かしをしてしまいます……明日の朝、きちんと起こしてくださいね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_2nd_anniv_11#originalText","id":"talk.vc.home_time_alice_uw_2nd_anniv_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……跟你聊天是很快乐，但我已经有点困了。剩下的就明天再说吧。","en":"As much as I enjoy chatting with you, I've gotten sleepy. Let us... continue this conversation tomorrow.","ja":"……お前と話をするのは楽しいですが私は少し眠くなってしまいましたこの続きは、また明日にしましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_2nd_anniv_12#originalText","id":"talk.vc.home_time_alice_uw_2nd_anniv_12","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……你半夜潜入女性的房间，本该以重罪论处的。就罚你让我看清楚你的面容吧。","en":"Sneaking into a lady's room at night is a grave sin. As penance... let me get a good look at your face.","ja":"……夜中に女性の部屋へ忍んで来るなど、本来であれば重罪ですよ罰として、お前の顔をよく見せなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_uw_2nd_anniv_1#originalText","id":"talk.vc.home_day_alice_uw_2nd_anniv_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"安息日结束，人民又开始辛勤工作……每次看到这幅景象，心里就有种幸福的感觉。","en":"With the day of rest at end, the citizens will get back to work... The sight of it pleases me somehow.","ja":"安息日を終えて、民たちがまた働き始める……この光景を見るとなんだか幸せな気持ちになるのです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_uw_2nd_anniv_2#originalText","id":"talk.vc.home_day_alice_uw_2nd_anniv_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你是不是积劳已久了？不要勉强自己，好好休息也是工作之一喔。","en":"Don't hide it—I know you are tired. I assure you, resting itself is a vital part of work.","ja":"疲れが溜まっているのではないですか? 無理をせずしっかり休むのも仕事のうちですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_uw_2nd_anniv_3#originalText","id":"talk.vc.home_day_alice_uw_2nd_anniv_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"虽然安息日还要工作，让人感到有些遗憾，但这也是骑士的职责。","en":"While I do feel that working on a day of rest is unfortunate, it is all part of a Knight's solemn duty.","ja":"安息日に仕事とは、少しばかり残念に感じてしまいますねですがこれも、騎士の責務です"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_uw_2nd_anniv_4#originalText","id":"talk.vc.home_day_alice_uw_2nd_anniv_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天玩得很心满意足，明天开始又能继续努力了。这就是你说的「充电」吗？","en":"Today's merriment brings tomorrow's productivity. I suppose this is the \"recharge\" concept you speak of?","ja":"今日しっかり楽しんだおかげで、また明日から頑張れます。これがお前の言う「充電」というものですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_1#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"新年快乐，希望你今年一整年都能安稳无事。","en":"I wish you a Happy Birthday. May you have a year of peace and comfort.","ja":"おめでとうございます今年一年、お前がずっと平穏でありますように"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_2#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在门口摆鱼头还真是有趣的习俗呢。听你谈起故乡，总是那么引人入胜。","en":"Decorating with fish heads is an amusing custom. Tales of your homeland always fascinate me.","ja":"魚の頭を飾る、というのは面白い風習ですね。お前の故郷の話はいつも興味深いです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_3#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"送礼给意中人，我觉得这是非常美妙的习俗。我、我的话……正在考虑！","en":"I think giving candy to one's beloved is a noble custom. Who's my Valentine, you ask? N-Not certain yet!","ja":"想う相手に贈り物をする、というのは素敵な風習だと思いますわ、私は……考え中です!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_4#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"既然是祝福女孩子的节日，那我想好好为赛鲁卡庆祝。我希望那孩子可以过得幸福。","en":"Since this is a festival for girls, I must honor Selka. I wish her all the happiness in the world.","ja":"女の子の祝いであれば、ぜひセルカのことを祝ってあげたいあの子には幸せでいて欲しいのです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_5#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"既然是回礼，那婉拒不收就是有失礼数。……是说你还打算送给谁？","en":"It would be rude not to accept a thank you gift... Now, whom is that other gift for?","ja":"贈り物の返礼であれば、受け取らないのは失礼に当たるというものです……それで他に誰の分があるのです?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_6#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我无法清楚辨别「玩笑」和「谎言」，所以在我面前，请你务必做个诚实的人。","en":"I can never tell when someone is lying. So I ask that you please never tell lies to me.","ja":"私には「冗談」と「嘘」の区別がうまくつきません。ですから、私の前では正直なお前でいてください"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_7#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这次休假，外出游玩是不错，但我也想修练剑技和术式。否则身手会变钝的。","en":"Using this time off for rest is a valid suggestion, but I would rather practice my sword and Sacred Arts.","ja":"この休暇は、遊ぶのもいいですが剣や術式の修練にも当てたいですでないと、体が鈍ってしまいますから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_8#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"雨天虽然让人忧郁，但少了雨滴，作物也会歉收。这也是索鲁斯大人的恩泽呢。","en":"As dreary as the rain is, our crops will suffer without it. Consider this a blessing from Solus.","ja":"雨は憂鬱ですが、この雨がないと作物の実りも悪くなりますこれもソルス様のお恵みですね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_9#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"就算你哪天到了遥不可及的地方，我也一定会赶往你的身边，不论发生何事。","en":"If you ever went far, far away... I would run to your side. No matter what the obstacles.","ja":"もしお前が遙か遠くに行ってしまったとしても、私は必ずお前の元に駆けつけます。何があっても、必ず"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_10#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_10","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你说的「海洋」，是怎样的地方呢？真想实地造访看看呢。","en":"What is this \"beach\" place you keep speaking of? I would like to visit it someday.","ja":"お前の言う「海」とは、どんなところなのでしょう。一度、実際に訪れてみたいですね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_11#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……我可以理解，如同你说的，明明在休假却要写大量的作业，的确很不讲理。","en":"Just as you say, being assigned piles of tasks during a time of rest is indeed unfair.","ja":"……お前の言うとおり、休暇中なのに大量の課題が出るのは理不尽だというのも理解できます"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_12#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_12","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"露那利亚大人的祭典与白天举行的祭典不同，给人一种静谧的感觉。","en":"Unlike daytime festivals, Lunaria's has a tranquil atmosphere to it.","ja":"昼間に行われる祭りと違いルナリア様の祭りは、なんだか静謐な感じがします"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_13#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_13","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"透过这种祭典的形式，就能自然地将点心和食物送给贫困的孩子们了呢。","en":"If I take on a festive appearance, then I shall be able to give food and sweets to children in need, yes?","ja":"この祭りのような体裁を取れば貧しい子どもたちにも、自然に菓子や食べ物を渡すことができますね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_2nd_anniv_15#originalText","id":"talk.vc.home_event_alice_uw_2nd_anniv_15","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"竟然还有送礼给孩子们的圣人，你的世界有许多祝福孩子成长的节日呢，真是美好。","en":"A saint who gives children gifts in winter? Your world surely celebrates children a lot. I love it.","ja":"子どもたちへ贈り物をする聖人といいお前の世界には、子どもを祝う祭りがたくさんあるのですね。素敵です"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_uw_2nd_anniv_1#originalText","id":"talk.vc.home_season_alice_uw_2nd_anniv_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"到了春天，就能看到金鸢狐的孩子在练习打猎。我非常喜欢那样的光景。","en":"The flying foxes teach their young to hunt in the springtime. I simply adore watching them.","ja":"春になると、トビギツネの子どもたちが、狩りの練習をしています私は、その光景がとても好きなのです"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_uw_2nd_anniv_2#originalText","id":"talk.vc.home_season_alice_uw_2nd_anniv_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在这炎炎夏日下，长时间外出会搞坏身体的。我们到树下去歇会儿吧。","en":"You mustn't stay in this inferno much longer—you'll hurt yourself. Come, let's rest in the shade.","ja":"この炎天下で長い間外にいると体調を崩します。少し木陰で休憩しましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_uw_2nd_anniv_3#originalText","id":"talk.vc.home_season_alice_uw_2nd_anniv_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"看见叶子飘落，即便心里明白那是自然的定律，还是难免会有寂寥之情。","en":"As I watch the falling blossoms, though I know it is Nature's will, I cannot help but feel sadness.","ja":"散りゆく葉を見ていると、それが自然の摂理だとわかってはいてもどうしても寂しくなってしまいます"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_uw_2nd_anniv_4#originalText","id":"talk.vc.home_season_alice_uw_2nd_anniv_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"呵呵，你的手摸起来也像冰块一样呢。我的手也是，你摸摸看，这么冰……","en":"Ooh, your hands are cold as ice. So are mine. Just feel how cold they are...","ja":"ふふ、お前の手も氷のように冷たくなっていますね私の手も、ほら、こんなに……"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_2nd_anniv_2#originalText","id":"talk.vc.home_bd_alice_uw_2nd_anniv_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我有时会忽然想起，小时候过生日时，也曾像这样有人在旁边给予祝福……","en":"A fleeting memory visits me at times...a memory of a childhood birthday. And the person I was with...","ja":"時折、ふと思い出すのです幼い頃の誕生日、こうして誰かに祝ってもらったことを……"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_2nd_anniv_3#originalText","id":"talk.vc.home_bd_alice_uw_2nd_anniv_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"桐人生日，我想送他衣服当礼物。因为要是坐视不管，他永远都会穿同一套衣服啊。","en":"I plan on getting Kirito something to wear for his birthday. That boy has no variety in his wardrobe.","ja":"キリトの誕生日には、何か服を贈ろうと思います。放っておくといつも同じ服を着ていますからね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_2nd_anniv_4#originalText","id":"talk.vc.home_bd_alice_uw_2nd_anniv_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"尤吉欧今天生日，我们一起来准备庆生吧。我想盛大地祝贺他一番。","en":"Let us plan a celebration for Eugeo's birthday. I wish to give him an extravagant party.","ja":"ユージオの誕生日、ふたりで祝いの準備をしましょう盛大にお祝いしてあげたいものです"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_2nd_anniv_6#originalText","id":"talk.vc.home_bd_alice_uw_2nd_anniv_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"要送亚丝娜什么，她才会高兴呢？你应该很清楚她的喜好吧？","en":"What do you suppose Asuna would like for her birthday? Wouldn't you know best?","ja":"アスナには、何を贈るのが喜ばれるでしょう。お前ならよく知っているのではないですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_2nd_anniv_7#originalText","id":"talk.vc.home_bd_alice_uw_2nd_anniv_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"拯救世界的绿之剑士……既然是她的生日，那我们也得盛大庆祝一番才行。","en":"The Green Swordswoman, savior of the world... We truly owe her a huge celebration on her birthday.","ja":"世界を救ってくれた、緑の剣士……彼女の生誕祭ですから、我々も盛大に祝わねばなりません"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_2nd_anniv_8#originalText","id":"talk.vc.home_bd_alice_uw_2nd_anniv_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"诗乃平时不太透露自己的喜好呢。让人十分犹豫该送她什么才好。","en":"Sinon never seems to put her own desires into words. That makes gift-giving a real puzzle.","ja":"シノンは、自らの好みなどはあまり口にしませんね贈る物にも迷ってしまいます"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_2nd_anniv_14#originalText","id":"talk.vc.home_bd_alice_uw_2nd_anniv_14","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你也很受莉兹贝特的照顾对吧？你有在思考怎么庆祝她的生日吗？","en":"You are also friends with Lisbeth, correct? Have you planned a birthday celebration for her?","ja":"お前もリズベットには世話になっているのでしょう?誕生日の祝いは考えているのですか"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_alice_uw_2nd_anniv_15#originalText","id":"talk.vc.home_bd_alice_uw_2nd_anniv_15","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"西莉卡真的很惹人怜爱呢。我想送她飞龙喜欢的东西，你觉得呢？","en":"Silica is indeed a sweet girl. I'm considering getting something for her pet dragon. What do you think?","ja":"シリカは本当にかわいらしいですね彼女には、飛竜の好物を贈ろうと思うのですが、どう思いますか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_uw_2nd_anniv_1#originalText","id":"talk.vc.home_etc_alice_uw_2nd_anniv_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我就知道你一定办得到。在下个使命下达之前，你就好好休养身体吧。","en":"I had every confidence in you. Now rest well until the next mission arrives.","ja":"お前ならやれると思っていました次の使命が下るまで、ゆっくりと体を休めてください"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_uw_2nd_anniv_2#originalText","id":"talk.vc.home_etc_alice_uw_2nd_anniv_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"有礼物送到了喔。看到大家这么仰慕你，我也与有荣焉，非常开心。","en":"A gift's arrived for you. Seeing how loved you are brings me such joy.","ja":"贈り物が届いていますよお前が皆に慕われていると自分のことのようにうれしくなります"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_uw_2nd_anniv_3#originalText","id":"talk.vc.home_etc_alice_uw_2nd_anniv_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"新的使命下达了。来，跟我一起挥舞手中的剑吧。你和我搭档是不可能败北的。","en":"A new task has arrived. Come, swing your sword with me! Together, we cannot be defeated.","ja":"新たな使命ですさあ、私と共に剣を振るいましょう我々ふたりなら、決して負けません"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_tales_1#originalText","id":"talk.vc.home_wait_alice_tales_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这种服装会让人静不太下心呢……请、请你不要一直盯着我看！","en":"I find this sort of clothing rather uncomfortable... P-Please don't stare!","ja":"このような服装は、なんだか落ち着きませんね……あ、あまり見ないでください!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_tales_2#originalText","id":"talk.vc.home_wait_alice_tales_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你现在的打扮也和平常不一样呢。这样……让我没那么不自在了。","en":"You too are dressed differently than usual. So I suppose... that shall relax me a little.","ja":"お前も、いつもとは違う格好をしているのですね。ならば……多少は落ち着きます"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_tales_3#originalText","id":"talk.vc.home_wait_alice_tales_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"因为对象是你，我才有办法展现这身装扮。在其他人面前我、我会害羞……","en":"I am only fine with you seeing me dressed like this. Not anyone else. It is f-far too embarrassing.","ja":"この装いは、お前だから見せるのです。ほかの人にはは、恥ずかしくて……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_tales_4#originalText","id":"talk.vc.home_wait_alice_tales_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在你身边至少不会感到无聊呢。这并不是在夸奖你喔。","en":"There is never a dull moment when I am with you. And I do not mean that as praise.","ja":"お前の傍にいると、少なくとも退屈することはありませんねほめているのではありませんよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_tales_5#originalText","id":"talk.vc.home_wait_alice_tales_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这身服装我穿不太习惯，不过很方便活动，挥剑不成问题。","en":"Though I am unfamiliar with this garment, it is easy to move in. Ideal for swinging my sword.","ja":"着慣れない衣装ですが動きやすくはあります剣を振るには充分です"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_tales_6#originalText","id":"talk.vc.home_wait_alice_tales_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"请把今天发生的事情藏在你心里就好，不可以告诉别人喔。","en":"Keep memories of this day locked inside your mind. Not a word to anyone else...understood?","ja":"今日のことは、お前の心の中だけに納めておきなさい他言は無用、ですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_tales_7#originalText","id":"talk.vc.home_wait_alice_tales_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我今天不太想见人……所以我会一直待在你的身边。","en":"I don't particularly wish to see anyone else today... So I shall stay by your side at all times.","ja":"今日は、あまり人と会いたくはないので……ずっと、お前の傍にいることにします"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_tales_8#originalText","id":"talk.vc.home_wait_alice_tales_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"其他女性也都会穿这样的服装吗？","en":"Do the other ladies all dress like this?","ja":"ほかの女性たちも、みんなこのような衣装を着ているのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_tales_9#originalText","id":"talk.vc.home_wait_alice_tales_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……你为什么不说话？如果对我这副模样有什么意见，就请你直说。","en":"Why are you silent? If you wish to say something about my appearance, then speak up.","ja":"……どうして黙っているのです私の姿に、言いたいことがあるならはっきりと言いなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_tales_1#originalText","id":"talk.vc.home_touch_alice_tales_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我戴了跟平常不同的发饰……你觉得怎么样？","en":"This hair ornament is unlike what I usually wear... What do you think of it?","ja":"普段とは違う髪飾りですが……お前はどう思いますか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_tales_2#originalText","id":"talk.vc.home_touch_alice_tales_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"不需要一直触碰，你也知道我就是我吧？","en":"You need not touch me so— you know it is I, do you not?","ja":"そんなに触らなくても私が私であることくらいお前にはわかるでしょう?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_tales_4#originalText","id":"talk.vc.home_touch_alice_tales_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"住、住手！我穿得比平常还要少，被、被你这样乱摸的话……","en":"N-Now, now! My garment is flimsier than usual. D-Do not touch me in that manner...","ja":"こ、こら!いつもより、薄着なのですからそ、そんな風に、されたら……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_tales_5#originalText","id":"talk.vc.home_touch_alice_tales_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我明白你对看不习惯的服装很感兴趣，但你不觉得该稍微克制一下那股欲望吗？","en":"I see that my unusual garb interests you. However, could you keep your urges in check?","ja":"見慣れぬ衣装に興味があるのはわかります。ですが、少しはその欲求を抑えようとは思わないのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_tales_1#originalText","id":"talk.vc.home_time_alice_tales_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"早安。……你那眼神是什么意思？请不要一直盯着我。","en":"Good morning. What? Why are you staring at me like that? Well, stop it.","ja":"おはようございます……なんですか、その目はジロジロ見ないでください"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_tales_4#originalText","id":"talk.vc.home_time_alice_tales_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天就不要外出，乖乖待在家里吧。嗯，这么做肯定比较好。","en":"Let us stay indoors all day. That is indeed a great idea.","ja":"今日は、外出せずに家の中で大人しくしていましょうええ、それがいいに決まっています"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_tales_7#originalText","id":"talk.vc.home_time_alice_tales_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"用这副打扮度过一整天后，也渐渐习惯了呢。话虽如此，我也不会想经常穿成这样。","en":"Spending the day in these clothes did acclimate me to them. However, I do not wish to make a habit of it.","ja":"さすがに1日この格好で過ごすと慣れてきますね。だからといって常用しようとは思いませんが"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_tales_10#originalText","id":"talk.vc.home_time_alice_tales_10","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……请你坦白告诉我。你对我这副模样……有什么想法！？","en":"Please, be honest. Me...in these clothes... What is your honest opinion of them?!","ja":"……正直に言ってください私の、この姿……お前は、どう思ったのですか!?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_tales_1#originalText","id":"talk.vc.home_day_alice_tales_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"星期一大家都会去上学吧。和一大群人一起上课，感觉好像很开心呢。","en":"Everyone goes to school on Monday, I see. Learning with a big group sounds rather fun.","ja":"月曜は、みな学校に行くのですね大勢で授業を受けるというのはなんだか楽しそうですね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_tales_2#originalText","id":"talk.vc.home_day_alice_tales_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在这个世界，有不少人会在安息日之外的日子休息呢。这个世界就是如此缤纷多样吗？","en":"People in this world rest even when it isn't a day of rest. Is there really such variety here?","ja":"この世界には、安息日以外でも休む者が結構多いのですねそれだけ多様な世界なのでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_tales_3#originalText","id":"talk.vc.home_day_alice_tales_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我很喜欢周末充满活力的氛围。因为只要身在其中，我也能变成普通的女孩，不再显眼。","en":"I love how lively weekends are. I can inconspicuously blend in with the crowd as a normal girl.","ja":"週末の活気は好きですその中に入ると、私もただの女の子になって、目立たなくなりますから"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_tales_4#originalText","id":"talk.vc.home_day_alice_tales_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"虽然有点累，但这个安息日过得很愉快。真舍不得它结束。","en":"I am a little tired, but this day of rest was enjoyable. I am sad to see it end.","ja":"少し疲れましたが、でも楽しい安息日でしたね。終わってしまうのが、名残惜しいです"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_tales_1#originalText","id":"talk.vc.home_season_alice_tales_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"穿着这身服装去赏花吗？嗯～我很想去看樱花，但要出现在大家面前就有点……","en":"A picnic? Well...I do want to see the cherry blossoms, but for others to see me dressed like this...","ja":"この衣装で、お花見ですか?うーん、桜の花は見たいですが皆の前に出るのはちょっと……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_tales_2#originalText","id":"talk.vc.home_season_alice_tales_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这身打扮比我平常穿着铠甲时还要凉爽呢。或许很适合在假日穿。","en":"This garment breathes much better than my armor. Perhaps this is ideal wear for a day of rest.","ja":"普段着ている鎧よりは涼しいですね休みの日を過ごすにはいいかもしれません"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_tales_3#originalText","id":"talk.vc.home_season_alice_tales_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"如果是在大家会戴上怪物头套的祭典上，就算我穿着这身服装，好像也不会很显眼。","en":"If there is a festival where people wear costumes, then I suppose I won't stand out in these clothes.","ja":"みなが怪物の被り物を着る祭りなら私がこの衣装を着ていても目立つことは無さそうですね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_tales_4#originalText","id":"talk.vc.home_season_alice_tales_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"穿着这身服装会觉得冬天的风很冰冷。我之所以和你紧紧靠在一起，就是为了抵挡冷风。","en":"Winter's breeze feels colder in these clothes. That is why I am sticking so close to you.","ja":"この衣装だと、冬の風が冷たく感じます。お前にくっついているのはその風を防ぐためです"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_tales_1#originalText","id":"talk.vc.home_etc_alice_tales_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你达成任务了啊。我就相信你一定做得到。","en":"I see you have completed a mission. I knew you could do it.","ja":"任務を達成したのですねお前なら必ずやり遂げると信じていましたよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_tales_2#originalText","id":"talk.vc.home_etc_alice_tales_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"那是要给你的礼物吧。……所以，那份礼物究竟是谁送来的？","en":"A gift has arrived for you. Now... who in the world sent it to you?","ja":"それはお前宛の贈り物ですね……それで、一体誰からの贈り物なのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_alice_tales_3#originalText","id":"talk.vc.home_etc_alice_tales_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"下个任务已经在等你了。如果由我和你来处理，肯定能顺利达成，毫无悬念吧。","en":"The next mission awaits. Working with you as a team, I have every confidence in our success.","ja":"次なる任務が待っています私とお前なら、いささかの不安もなく達成できることでしょう"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_integrator_enhance_wait_1#originalText","id":"talk.vc.home_alice_integrator_enhance_wait_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今后我要为了我所追求的事物而战。","en":"From now on, I'm going to fight for what I want to.","ja":"これから私は私自身が求めるもののために戦う"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_integrator_enhance_touch_1#originalText","id":"talk.vc.home_alice_integrator_enhance_touch_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……我已经没事了。我会往前进，为了你，以及我所追求的东西。","en":"...I'm fine I will press forward. For what you and I desire.","ja":"……私は、もう大丈夫前に進みますお前と、私の求めるもののために"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_integrator_enhance_touch_4#originalText","id":"talk.vc.home_alice_integrator_enhance_touch_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你愿意听听我的决心吗？","en":"Will you listen to my resolve?","ja":"私の決意を聞いてくれますか?"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_real_student_wait_1#originalText","id":"talk.vc.home_alice_real_student_wait_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"穿上这身衣服后想在这里也能继续作为一个骑士，心里就安心了许多。","en":"With these clothes, I can be a knight here as well... how reassuring.","ja":"この服を身に纏うとこちら側でも騎士でいられる……そんな気がして、心強いのです"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_real_student_wait_2#originalText","id":"talk.vc.home_alice_real_student_wait_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"虽然少了盔甲令我感到有点不安，但不可思议的是这身衣服让我有种必须要振作起来的感觉。","en":"I feel a little tense without my armor, but these clothes give me confidence.","ja":"鎧がなく、少し心許ないですが不思議と気が引き締まる服ですね"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_real_student_wait_3#originalText","id":"talk.vc.home_alice_real_student_wait_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这身装扮的话，和你一起走在街上其他人应该也不会感到奇怪吧？来，请你带路吧。","en":"It won't be weird walking around town in this outfit, will it? If not, let's get going.","ja":"この格好であれば、お前と街を歩いていてもおかしくはないのでしょう?さぁ、案内してください"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_alo_wait_1#originalText","id":"talk.vc.home_alice_alo_wait_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"正是在危急情况下才更加考验身为骑士的心态！","en":"The real test of being a knight is when you're in a pinch!","ja":"危急の事態にこそ騎士の心構えが問われるのです!"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_alo_wait_2#originalText","id":"talk.vc.home_alice_alo_wait_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"想快点成为龙骑士翱翔广大天空看看。","en":"I want to hurry up and become a dragon knight so I can soar the skies!","ja":"早く竜騎士になって大空を駆ってみたいです"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_alo_wait_3#originalText","id":"talk.vc.home_alice_alo_wait_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这个世界，总觉得和Underworld有些相似之处是这美丽的森林和蔚蓝的天空吗？","en":"This world is similar to my world. Like it's beautiful forests and blue skies.","ja":"この世界は、アンダーワールドにどこか似ています美しい森や空の青さでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_alo_wait_4#originalText","id":"talk.vc.home_alice_alo_wait_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在这世界里，也存在着许多技巧成熟的骑士和神圣术师。我也必须精进自己才行。","en":"They also have plenty of skilled knights and Sacred Arts users. I must work harder!","ja":"この世界にも、手練の騎士や神聖術師がたくさんいるのですね私も精進せねば"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_alo_touch_1#originalText","id":"talk.vc.home_alice_alo_touch_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这对大耳朵让我有种变成金鸢狐的感觉。","en":"I feel like a big-eared golden flying fox!","ja":"この大きな耳キントビギツネになった気分です"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_alo_touch_2#originalText","id":"talk.vc.home_alice_alo_touch_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在那边的世界，大概就在那一带记载着集成骑士的排序呢。","en":"In my world, an Integrity Knight's rank is inscribed right around there.","ja":"あちらの世界ではそのあたりに整合騎士の序列が記されていましたね"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_swimsuit_wait_1#originalText","id":"talk.vc.home_alice_swimsuit_wait_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这衣服，无防备到让人傻眼的地步了…","en":"It's amazing how exposed this outfit is...","ja":"この服は、呆れるくらいに無防備ですね…"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_swimsuit_touch_1#originalText","id":"talk.vc.home_alice_swimsuit_touch_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"不，不要紧！ 头发什么的我自己能擦干……","en":"I'm f-fine! I can do my own hair...","ja":"だ、大丈夫です!自分の髪くらい、自分で拭けます……"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_swimsuit_touch_2#originalText","id":"talk.vc.home_alice_swimsuit_touch_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"快、快住手！就是因为有像你这样的人在，这类衣服才令人觉得危险！！","en":"S-Stop! It's because of people like you this outfit is dangerous!","ja":"や、やめなさい!お前のような者がいるからこういった服は危険なのです!!"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_edith_cos_wait_1#originalText","id":"talk.vc.home_alice_edith_cos_wait_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"啊啊啊啊……我的铠甲在哪里啊！","en":"Ahhhh... Where did I put my armor?!","ja":"ああああ……私の鎧はどこですかっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_edith_cos_wait_2#originalText","id":"talk.vc.home_alice_edith_cos_wait_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"比我的衣服还要凉爽呢。其实伊迪丝阁下非常怕热对吧？","en":"This sure is breezier than my regular clothes. I guess Eydis doesn't like the heat?","ja":"私の服より涼しいですねイーディス殿は実は暑がりなのでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_edith_cos_touch_1#originalText","id":"talk.vc.home_alice_edith_cos_touch_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"就连发型也被整理的和伊迪丝阁下一模一样……","en":"To think I'm going to mimic Eydis down to her haircut...","ja":"髪型までイーディス殿とお揃いにされてしまいました……"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_edith_cos_touch_2#originalText","id":"talk.vc.home_alice_edith_cos_touch_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"感觉头比平时还要重。是因为头发绑的位置比较高吗？","en":"My head feels a bit heavier than usual. I wonder if it's because I tied this up too high?","ja":"いつもより少し頭が重く感じます高い位置で結んでいるからでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_edith_cos_touch_3#originalText","id":"talk.vc.home_alice_edith_cos_touch_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这样看着我，身体像要被看穿个洞似的！呜……为什么要做这样的事啊……","en":"Why are you looking at me like that?! Grr...the nerve...","ja":"そんなに見られては穴が開きます!うぅ……何故このようなことに……"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_edith_cos_touch_4#originalText","id":"talk.vc.home_alice_edith_cos_touch_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"不要这样戳我……！不收敛一点的话，我要跟叔叔告状哦！","en":"Don't you dare touch me like that...! You better back off or I'll tell uncle!","ja":"そんなに突かないでください……!いい加減にしないと小父様に言いつけますよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_halloween_wait_1#originalText","id":"talk.vc.home_alice_halloween_wait_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"衣长这、这么短的服装，才不是我自愿穿的！","en":"T-This short costume wasn't my idea!","ja":"こ、このような丈の短い衣装私の意志ではありません!"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_halloween_touch_1#originalText","id":"talk.vc.home_alice_halloween_touch_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"居然要我用这身服装应战？你是笨蛋吗！？","en":"Y-You want me to fight in this?! You must be an idiot!","ja":"こ、この衣装で戦えと?お前は馬鹿ですか!"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_halloween_touch_2#originalText","id":"talk.vc.home_alice_halloween_touch_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"才不让你恶作剧呢！我可是有好好准备糖果的哦！ ","en":"N-No tricks! I've got your treats right here! ","ja":"い、いたずらはさせませんよちゃんと菓子は用意しましたから! "},"kind":"dialogue"},{"uid":"talk.vc.home_alice_uw_2022_new_year_wait_1#originalText","id":"talk.vc.home_alice_uw_2022_new_year_wait_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"只要穿上这个，总是不可思议地感到安心。","en":"May not look it, but weirdly enough, these clothes are really  comfortable.","ja":"これを着ていると不思議と心が安らぎます"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_uw_2022_new_year_wait_2#originalText","id":"talk.vc.home_alice_uw_2022_new_year_wait_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"又是新的一年了呢。我姑且，还是来跟你打声招呼。","en":"Just dropped by to wish you a happy new year!","ja":"新しい年を迎えましたね一応、挨拶をしに来ました"},"kind":"dialogue"},{"uid":"talk.vc.home_alice_uw_2022_new_year_wait_3#originalText","id":"talk.vc.home_alice_uw_2022_new_year_wait_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"哈啊……好想喝点茶什么的呢。","en":"Hmm... I could use a hot cup  of tea right now.","ja":"はぁ……お茶でも飲みたいですね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_1st_1#originalText","id":"talk.vc.home_wait_alice_1st_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"天气好的日子里，雨缘经常像这样晒太阳，跟某个人还真像呢。","en":"On clear days like this, Amayori likes to sunbathe. Reminds me of someone I know.","ja":"天気のいい日は、雨縁はよくこうして日に当たっていますどこかの誰かとそっくりですね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_1st_2#originalText","id":"talk.vc.home_wait_alice_1st_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"要是能像剑术跟神圣术一样，也有个人教导我下厨就好了……","en":"I wish I had someone to teach me to cook, just as I do for the sword and Sacred Arts.","ja":"剣や神聖術のように料理も教えてくれる人がいればよいのですが……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_1st_3#originalText","id":"talk.vc.home_wait_alice_1st_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你看起来闲得发慌呢，那么就来与我比划一场吧。来，拿起你的剑。","en":"You look bored. Fancy a duel? Come on then, draw your sword.","ja":"手持ち無沙汰のようですねならば立ち合いましょうさあ、剣を取りなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_1st_4#originalText","id":"talk.vc.home_wait_alice_1st_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"集成骑士的使命是我的荣耀。我以性命起誓，我一定会守护好人界。","en":"I have the honor of being an Integrity Knight. I will protect the Human Empire with my life.","ja":"私は整合騎士の使命に誇りを持っていますこの命にかけて人界を護ります"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_1st_9#originalText","id":"talk.vc.home_wait_alice_1st_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……让我躲一下！伊迪丝阁下不肯罢休，硬要找我一起去洗澡！","en":"Please...help me hide! Eydis is pressuring me to bathe with her again!","ja":"……少し匿ってください!イーディス殿が、執拗にお風呂に誘ってくるのです!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_1st_1#originalText","id":"talk.vc.home_touch_alice_1st_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……这次就算了。今后不要再把我当小孩子一样逗弄。","en":"Just this once, I'll allow it... But treat me like a child again, and you'll pay dearly.","ja":"……今回だけは許します以降、二度とこの私を子どものように扱わないように"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_1st_2#originalText","id":"talk.vc.home_touch_alice_1st_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……我有时会觉得长头发很妨碍战斗，但并不会想把头发剪短。","en":"Long hair is a liability in combat... That is what some people say. But I don't want to cut my hair.","ja":"……長い髪は戦闘の邪魔そう考えることはありますが切りたくはないのです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_1st_4#originalText","id":"talk.vc.home_touch_alice_1st_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你这个人实在是……竟然不知教训，一直把手伸过来，看来你很不想要这只手了呢。","en":"You just don't know when to quit, do you...? Clearly you don't care if you lose your hands.","ja":"お前というヤツは……懲りずに何度も手を伸ばしてよほど手が要らないようですね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_1st_5#originalText","id":"talk.vc.home_touch_alice_1st_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你以为我的身体可以让人如此随意触碰吗？你把我当成了什么啊？","en":"Do you really think I would let you touch me so easily? Who do you think I am?","ja":"そうやすやすと、体を触らせると思っているのですか私を何だと思っているのです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_1st_6#originalText","id":"talk.vc.home_touch_alice_1st_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……唉，总觉得悲哀了起来。为什么我会被你这种人……","en":"Ohh...now I'm feeling melancholy. Why must I feel so vulnerable around the likes of...","ja":"……はあ、なんだか悲しくなってきましたどうして私はこのような者に……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_1st_1#originalText","id":"talk.vc.home_time_alice_1st_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"一沐浴到索鲁斯的光芒，就会自然醒来呢。走，准备外出了。","en":"Solus's light never fails to wake me early. Come, let's go outside.","ja":"ソルスの光を浴びると目が覚めますねほら、外へ行きますよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_1st_4#originalText","id":"talk.vc.home_time_alice_1st_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"看到你睡午觉，连我也会跟着想睡。要睡的话请你回房间睡。","en":"Seeing you napping like that is making me sleepy. If you must nap, do so indoors.","ja":"お前が昼寝をしているとこちらまで眠くなってしまいます寝るなら、部屋の中でなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_1st_7#originalText","id":"talk.vc.home_time_alice_1st_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"喂！要等晚餐煮好才可以开动！不准偷吃！","en":"Hey! No dinner until it's ready! I will not tolerate sneaking bites off the plate!","ja":"こら!夕食は準備ができてからです!つまみ食いは許しません!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_1st_10#originalText","id":"talk.vc.home_time_alice_1st_10","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这样的夜晚会令人不禁想喝点酒，我也能懂这种心情。","en":"On nights like this, I can understand the desire to have a drink of wine.","ja":"こんな夜は、少しお酒を飲みたくなる気持ちもわかります"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_1st_1#originalText","id":"talk.vc.home_day_alice_1st_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"下一个任务即将开始，我们要上紧发条。","en":"Our next mission is about to start. Let's give it our all.","ja":"次の任務が始まりますね気を引き締めて臨みましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_1st_2#originalText","id":"talk.vc.home_day_alice_1st_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"持续出任务，的确会渐渐累积疲劳。晚上要记得好好休息喔。","en":"Doing mission after mission really takes its toll on the body. Be sure to rest well at night.","ja":"任務が続くと、確かに疲れが溜まってきます夜はゆっくり休むのですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_1st_3#originalText","id":"talk.vc.home_day_alice_1st_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"就算是安息日，整天都在睡觉实在令人无法苟同。","en":"Don't think you can get away with napping all day just because it's a Day of Rest.","ja":"安息日だからといって一日中寝ているのはどうかと思いますよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_1st_4#originalText","id":"talk.vc.home_day_alice_1st_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"真是令人开心的假日。都是托了你的福，我要向你道谢。","en":"That was a fun Day of Rest. Thank you for making it so.","ja":"楽しい休日でしたお前のおかげです礼を言っておきましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_1st_1#originalText","id":"talk.vc.home_season_alice_1st_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"天气一天比一天暖和了起来呢。你的睡意是不是也越来越浓了呢？","en":"The days have been getting warmer. I only hope this won't make you even lazier.","ja":"日々、少しずつ暖かくなっていきますね。お前の眠気も強くなるのではないですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_1st_2#originalText","id":"talk.vc.home_season_alice_1st_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"不管有多么热，穿得过于清凉的话，身、身为集成骑士实在……","en":"No matter how hot the weather, an esteemed I-Integrity Knight mustn't dress sk-skimpily.","ja":"たとえどれほど暑くてもあまりに薄着になるのはせ、整合騎士として……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_1st_3#originalText","id":"talk.vc.home_season_alice_1st_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"金木樨会在这个季节开花，望着小小的花朵，便令人心情雀跃。","en":"The fragrant olives bloom this time of year. Seeing the tiny buds makes my heart flutter.","ja":"この季節にはキンモクセイが咲くのです。小さい花たちを見ていると、心が弾みます"},"kind":"dialogue"},{"uid":"talk.vc.home_season_alice_1st_4#originalText","id":"talk.vc.home_season_alice_1st_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"有冰在河里漂流呢。……很久以前我好像也和你一起看过这样的风景。","en":"I see ice in the rivers now. I have the feeling...you and I beheld this scene long ago.","ja":"川を氷が流れていますね……遠い昔も、お前とこんな風景を見たような気がします"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_sleeping_1#originalText","id":"talk.vc.home_wait_alice_uw_sleeping_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我不允许不合礼节的事情！但是……如果只是待在身旁的话我可以答应。","en":"I will not tolerate rudeness. But...if you're only standing next to me...","ja":"無礼なことは許しませんただ……隣にいるだけなら許可しましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_sleeping_2#originalText","id":"talk.vc.home_wait_alice_uw_sleeping_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"只要和你在一起，不可思议地总是能获得深沉且充实的睡眠。","en":"It's strange whenever I am with you. I feel calm and can just fall asleep at any moment.","ja":"お前といると、不思議なことに深く、そして満ち足りた眠りにつくことができるのです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_sleeping_3#originalText","id":"talk.vc.home_wait_alice_uw_sleeping_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你要去哪里？不允许你擅自离开！这是你让我如此担心的惩罚！","en":"Where do you think you're going? Don't just wander around! I'll teach you for worrying me!","ja":"どこへ行くのですか勝手に離れることは許しません私をあれだけ心配させた罰です"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_sleeping_4#originalText","id":"talk.vc.home_wait_alice_uw_sleeping_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"安心吧，就算你睡着，我也会一直守护你的。","en":"Don't worry. Even if you fall asleep, I'll be here to protect you.","ja":"安心なさいお前が寝てしまっても私がお前を守ります"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_sleeping_5#originalText","id":"talk.vc.home_wait_alice_uw_sleeping_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这样令人害羞的地方要是被其他人看见的话……","en":"If someone was to see us like this...","ja":"このようなところを他の誰かに見られでもしたら……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_sleeping_6#originalText","id":"talk.vc.home_wait_alice_uw_sleeping_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"像现在这样，偶尔悠闲地把战斗的事都抛诸脑后，感觉也不错呢。","en":"You know, it's good to be able to forget about fighting and just take it easy from time to time.","ja":"こうして、戦いを忘れてゆっくりするのも、たまにはいいものですね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_sleeping_7#originalText","id":"talk.vc.home_wait_alice_uw_sleeping_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"看到有活力的你的脸，是安心感吗……心情会变得比较沉稳。","en":"Whenever I see your smile... I feel a sense of ease and calm within me.","ja":"元気なお前の顔を見ていると安心感というか……心が穏やかになるのです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_sleeping_8#originalText","id":"talk.vc.home_wait_alice_uw_sleeping_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你看看你，被子盖好点！把肩膀露在被子外睡觉的话会感冒的！","en":"Hey! Put some clothes on! You'll catch a cold if you sleep with your shoulders out like that.","ja":"ほら、もっと夜具を被りなさい肩を出したまま寝ると風邪を引きますよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_uw_sleeping_9#originalText","id":"talk.vc.home_wait_alice_uw_sleeping_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"睡着了吗？真的到处都是空隙的男人呢，……呵呵，真的到处都是空隙～","en":"Did you fall asleep? You're a man of many weaknesses... Hehe, only weaknesses.","ja":"眠ってしまったのですか隙の多い男ですね……ふふ、本当に隙だらけです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_sleeping_1#originalText","id":"talk.vc.home_touch_alice_uw_sleeping_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"右眼已经治好了。只要有神圣力的话那种程度的伤是可以治愈的。","en":"My right eye is already better. With sacred power, even wounds like this can be treated.","ja":"もう右目は治りました神聖力さえあればあの程度の傷は治癒するのです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_sleeping_2#originalText","id":"talk.vc.home_touch_alice_uw_sleeping_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"……你、究竟把女性的头发当作什么啊！居然那样轻浮地……","en":"...What are your thoughts on women's hair? If we were to talk casually...","ja":"……お前は、女性の髪を何だと思っているのですそんなに、気軽に……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_sleeping_3#originalText","id":"talk.vc.home_touch_alice_uw_sleeping_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"是不是，有点太过放肆了呀你？就算是你，也稍微懂点轻重……","en":"Getting a little comfortable are we? Don't think you can do as you please...","ja":"少し、馴れ馴れしいのではないですか。いくらお前でも加減をわきまえなさい……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_sleeping_4#originalText","id":"talk.vc.home_touch_alice_uw_sleeping_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"呀！？现在快停下来！因为、我没穿盔甲！","en":"Agh?! Stop that this instant! I'm not wearing any armor!","ja":"ひゃっ!?今はやめなさい!鎧を、着けていないのですから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_sleeping_5#originalText","id":"talk.vc.home_touch_alice_uw_sleeping_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"不要再离我更近了…………不过，不要离开我请保持……这个距离。","en":"Don't try to get any closer... But don't leave... Stay right there...","ja":"それ以上近寄ってはダメです……でも、離れないでその距離に……いてください"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_sleeping_6#originalText","id":"talk.vc.home_touch_alice_uw_sleeping_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"虽说我们睡在同一张床上但我还没有允许你做所有的事情哦！","en":"Don't think just because we're sharing a bed together doesn't mean I 100% forgive you!","ja":"いくら共寝してるからといって全てを許したわけではありません!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_sleeping_7#originalText","id":"talk.vc.home_touch_alice_uw_sleeping_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你的这双，纤细的手改变了我……还有世界的命运了呢。","en":"With these hands you changed the fate of the world... and me...","ja":"お前のこの細い手が私の……そして世界の運命を変えてしまったのですね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_alice_uw_sleeping_8#originalText","id":"talk.vc.home_touch_alice_uw_sleeping_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"好好躺着不要动，你这么想要温暖的话……握着彼此的手吧。","en":"Don't move around so much! If you're cold... we can hold hands.","ja":"じっとしていなさいそれほど温もりがほしいなら……手を、触れ合いましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_sleeping_1#originalText","id":"talk.vc.home_time_alice_uw_sleeping_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"早上了呢……虽然感觉有点可惜，但起床吧！","en":"Looks like it's morning already... I wish I could stay a little longer, but let's get up.","ja":"朝……ですね少しばかり名残惜しいですが起きてしまいましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_sleeping_2#originalText","id":"talk.vc.home_time_alice_uw_sleeping_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"还在睡吗？……呵呵，那张脸还真是毫无防备呢～","en":"Are you still asleep? ...Hehe, you look sound asleep.","ja":"まだ寝ているのですか?……ふふ、その顔はずいぶん油断しているようですね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_sleeping_4#originalText","id":"talk.vc.home_time_alice_uw_sleeping_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"偶尔陪你一起午睡也不错呢～","en":"You know, taking a nap with you from time to time isn't so bad.","ja":"たまにはお前に付き合って午睡もいいものですね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_sleeping_5#originalText","id":"talk.vc.home_time_alice_uw_sleeping_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"被暖气唤起的无法言喻的睡意，不是和你在一起的话也不会这么想睡呢。","en":"This heat is sure to make anyone drowsy. But even if you weren't here, I wouldn't succumb to it.","ja":"なんとも眠気を誘う暖かさですお前でなくても、これでは睡魔にあらがえません"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_sleeping_7#originalText","id":"talk.vc.home_time_alice_uw_sleeping_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"差不多该准备晚餐了，……怎样啦，那张脸我也是稍微有些进步了好吗！","en":"Shall we start preparing dinner? ...What's with that look? Listen, I've gotten better!","ja":"そろそろ夕食を作りましょうか……なんですか、その顔は私だって、少しは上達したのです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_sleeping_8#originalText","id":"talk.vc.home_time_alice_uw_sleeping_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"晚上我时常会做恶梦。但是，和你一起的期间，总是能梦到快乐的事情。","en":"I often got nightmares whenever I slept at night. But with you, I've seen nothing but pleasant dreams.","ja":"夜はよく、悪夢を見ていましたでも、お前と一緒の間は楽しい夢ばかり見るのです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_sleeping_10#originalText","id":"talk.vc.home_time_alice_uw_sleeping_10","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在寂静之中，总让我有这世界……只剩下你和我两个人似的感觉。","en":"Being with you in this silence feels like we're the only ones in this world...","ja":"静寂の中にいると、世界にお前と私、ふたりしか存在しない……そんな気がするのです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_alice_uw_sleeping_11#originalText","id":"talk.vc.home_time_alice_uw_sleeping_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你还醒着吗？快点睡吧，我可是不会让你看到我的睡脸的～","en":"Still awake, are we? Hurry up and get some shuteye. I won't let you see me sleeping.","ja":"まだ起きているのですか?早く眠ってしまいなさい私の寝顔は見せませんよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_uw_sleeping_1#originalText","id":"talk.vc.home_day_alice_uw_sleeping_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"别一直睡了，一口作气起床吧！……不要摆出那样的表情嘛。","en":"Don't go on sleeping forever! Time to wake up. ...Don't look at me like that!","ja":"いつまでも寝ていないで思い切って起きましょう……そんな顔をしないでください"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_uw_sleeping_2#originalText","id":"talk.vc.home_day_alice_uw_sleeping_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"回去还是能像现在这样见面的，差不多该完成我们彼此的责任了。","en":"We'll be able to meet again like this when you go back. So let's finish up what we need to do.","ja":"帰ればまた、こうして会えるのですから、そろそろお互いの務めを果たしましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_uw_sleeping_3#originalText","id":"talk.vc.home_day_alice_uw_sleeping_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"虽然我也喜欢安息日的欢闹，但只有两人的安静时光也令人难以割舍……","en":"I do like the calmness on my days off, but being with you is something I can't toss away either.","ja":"安息日の賑やかさも好きですが、ふたりだけの静寂も、また捨てがたい……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_uw_sleeping_4#originalText","id":"talk.vc.home_day_alice_uw_sleeping_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"会觉得安息日即将结束，且令人感到寂寞，是从遇到你开始。","en":"Ever since I met you, I feel lonely when my days off come to an end.","ja":"安息日が終わるのを寂しく思うようになったのは、お前に出会ってからです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_1#originalText","id":"talk.vc.home_event_alice_uw_sleeping_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"新的一年的开始呢。那时候能和你一起迎接新的一年，我感到很开心。","en":"Looks like it's the start of a new year. I'm glad I get to see you during this time.","ja":"新たな年の始まりですねその時をお前と迎えられたことうれしく思います"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_2#originalText","id":"talk.vc.home_event_alice_uw_sleeping_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"大豆非常有营养价值，是祈愿身体健康时非常适合吃的食物。","en":"Beans are a great source for nutrients. They're the perfect food if you want to be healthy!","ja":"豆は滋養にいい健康祈願に食べるには適している食べ物です"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_3#originalText","id":"talk.vc.home_event_alice_uw_sleeping_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在你那边的世界的习惯，是会赠予喜欢的人点心对吧……这个是、那个……就是、那个……啦。","en":"In your world, you hand sweets to those who you care for, correct? ...Well, here you go...","ja":"お前の世界の風習では、好きな相手に菓子を渡すのですよね……これは、その……ソレ、です"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_4#originalText","id":"talk.vc.home_event_alice_uw_sleeping_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"为了庆祝女孩子成长的庆典……很棒呢！没有比孩子的成长更令人开心的事了。","en":"A ceremony to celebrate a girl growing up... How lovely. There's nothing happier than that.","ja":"女子の成長を祝うお祭り……素敵ですね、子どもの成長はなにより喜ばしいものです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_5#originalText","id":"talk.vc.home_event_alice_uw_sleeping_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这要、给我吗！？……谢谢。我绝对不会忘记这件事的。","en":"Is this for me?! ...Thank you! I will never forget this.","ja":"これを、私にっ!?……ありがとうこのことは、決して忘れません"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_6#originalText","id":"talk.vc.home_event_alice_uw_sleeping_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我们不要再说谎了。不是因为禁忌，是对彼此的信赖关系不好。","en":"Let's stop with the lies. Not because it's taboo, but because we trust each other.","ja":"嘘はやめましょう禁忌だからではなく、お互いの信頼のために、よくありません"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_7#originalText","id":"talk.vc.home_event_alice_uw_sleeping_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我还不习惯长时间的休息。所以……我们一起想想要做什么吧。慢慢的，两人一起。","en":"I haven't gotten used to having long breaks. So...let's think of something to do. Just us.","ja":"長い休息には慣れていませんだから……何をするか考えましょうゆっくりと、ふたりで"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_8#originalText","id":"talk.vc.home_event_alice_uw_sleeping_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"只要到下雨的日子《雨缘》总是很开心呢。是因为跟名字有关吗？得稍微陪牠玩一下才行。","en":"Rainy days are Amayori's favorite. \"Rain\" is in her name, after all, so I have to let her play.","ja":"雨の日は《雨縁》が喜ぶのです名前に縁があるからでしょうか少しは遊んであげないと"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_9#originalText","id":"talk.vc.home_event_alice_uw_sleeping_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"被分裂的恋人的故事……很令人伤心呢。一想到要是自己遇到同样的情况就……","en":"A tale of two lovers torn apart... How sad. To think if that happened to me...","ja":"引き裂かれる恋人の話……悲しいですね。もし自分がそうなったらと思うと……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_10#originalText","id":"talk.vc.home_event_alice_uw_sleeping_10","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"好像在准备夏至祭典呢！呵呵，因为是你，所以可能从现在就在考虑要吃些什么了呢。","en":"Looks like they're getting ready for the Summer Solstice Festival. Hehe, I wonder what you should eat.","ja":"夏至祭の準備をしているようですねふふ、お前のことだから、今から何を食べるか考えているのでしょう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_alice_uw_sleeping_11#originalText","id":"talk.vc.home_event_alice_uw_sleeping_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"因为长假的关系，身体可能变得有些迟钝，必须要再重新锻炼呢！","en":"My body will probably get a little out of shape on long breaks. I'll have to keep up my training!","ja":"長い休みで、少し体が鈍ってしまったかもしれません改めて鍛え直さねば"},"kind":"dialogue"}]};
